    if (category && !["HIGHLIGHTS", "TUTORIALS", "GYM"].includes(category.toUpperCase())) {
      throw new BadRequestError("Invalid category. Allowed categories are HIGHLIGHTS, TUTORIALS, or GYM.");
    }
