    const approved = regs.filter((r5) => r5.status === "APPROVED").length;
    const waitlisted = regs.filter((r5) => r5.status === "WAITLISTED").length;
    const pending = regs.filter((r5) => r5.status === "PENDING").length;
    let passedWeighinCount = 0;
